      }
    }
  ],
  "dataModelSchema": {
    "data": {
      "calendar": {
        "items": [
          {
            "entityId": {
              "type": "string",
              "description": "缴费日历事件的唯一标识符",
              "sampleValue": "utility-bill-due-001"
            },
            "title": {
              "type": "string",
              "description": "缴费日历事件标题",
              "sampleValue": "水电缴费"
            },
            "dtStart": {
              "type": "string",
              "description": "缴费日期展示文本",
              "sampleValue": "7月12日"
            },
            "description": {
              "type": "string",
              "description": "缴费状态提醒短文本",
              "sampleValue": "快欠费"
            }
          }
        ]
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/bolt_fill.svg",
      "description": "闪电实心图标，适合表示用电、水电缴费或账单能源属性，黑色图形适合放在浅色表面。"
    },
    {
      "src": "resources/base/media/calendar_fill.svg",
      "description": "日历实心图标，适合表示缴费日、日程提醒或日期查看入口，黑色图形适合放在浅色表面。"
    }
  ]
}

